static ValidationResult validate(Order o){
 if(o==null)return ValidationResult.error("order.required");
 if(o.customerName()==null||o.customerName().isBlank())return ValidationResult.error("customer.required");
 if(o.total().signum()<=0)return ValidationResult.error("total.positive");
